/// Helper function to handle peripheral versions with underscores.
/// For a version like "v1_foo_bar", this generates all prefix combinations:
/// - "kind_v1"
/// - "kind_v1_foo"
/// - "kind_v1_foo_bar"
fn foreach_version_cfg(
    cfgs: &mut common::CfgSet,
    kind: &str,
    version: &str,
    mut cfg_fn: impl FnMut(&mut common::CfgSet, &str),
) {
    let parts: Vec<&str> = version.split('_').collect();

    // Generate all possible prefix combinations
    for i in 1..=parts.len() {
        let partial_version = parts[0..i].join("_");
        let cfg_name = format!("{}_{}", kind, partial_version);
        cfg_fn(cfgs, &cfg_name);
    }
}

fn main() {
    let mut cfgs = common::CfgSet::new();
    common::set_target_cfgs(&mut cfgs);

    if std::env::var("CARGO_FEATURE_RT").is_err()
        && std::env::var("CARGO_CFG_TARGET_OS") == Ok("none".to_string())
        && std::env::var("CARGO_CFG_TARGET_ARCH") == Ok("arm".to_string())
    {
        println!("cargo::warning=Building for bare-metal ARM without `rt` feature: interrupts will loop forever.");
    }

    let chip_name = match env::vars()
        .map(|(a, _)| a)
        .filter(|x| x.starts_with("CARGO_FEATURE_STM32") && x != "CARGO_FEATURE_STM32_HRTIM")
        .get_one()
    {
        Ok(x) => x,
        Err(GetOneError::None) => panic!("No stm32xx Cargo feature enabled"),
        Err(GetOneError::Multiple) => panic!("Multiple stm32xx Cargo features enabled"),
    }
    .strip_prefix("CARGO_FEATURE_")
    .unwrap()
    .to_ascii_lowercase();

    eprintln!("chip: {chip_name}");

    // Private incremental audit: hardware remains in the PAC. Only implemented
    // HAL drivers may emit driver traits; absent drivers are NOT absent hardware.
    let die47c = chip_name.starts_with("stm32h543") || chip_name.starts_with("stm32h553");
    cfgs.declare("stm32h5_47c");
    cfgs.set("stm32h5_47c", die47c);
    let die47a = ["stm32h5e4", "stm32h5e5", "stm32h5f4", "stm32h5f5"].iter().any(|prefix| chip_name.starts_with(prefix));
    cfgs.declare("stm32h5_47a");
    cfgs.set("stm32h5_47a", die47a);
    let driver_available = |kind: &str| !(die47c || die47a) || matches!(kind,
        "rcc" | "pwr" | "gpio" | "gpdma" | "usart" | "can" |
        "timer" | "spi" | "usb" | "usbram" | "icache" | "dcache" | "exti" | "crs" | "sbs" | "otg" | "rtc"
    );


    for p in METADATA.peripherals {
        if let Some(r) = &p.registers {
            // The AES driver enables the peripheral's clock, which the metadata does not
            // know for the AES of some chips (STM32L0, L1, F423): no driver there.
            if r.kind == "aes" && p.rcc.is_none() {
                continue;
            }
            if !driver_available(r.kind) { continue; }
            cfgs.enable(r.kind);
